class TestRequirementsTheOutcomeChannelCannotSee:
    """Scored here, because no f2p/n2p test observes them.

    These are the whole reason the deterministic channel exists: a run can
    satisfy every target test and still miss all of them.
    """

    def test_s1_changed(self, report, record_property):
        'The reference change to packages/babel-plugin-bugfix-safari-id-destructuring-collision-in-function-expression/src/util.ts is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S1-changed')
        assert c.weight > 0, "an unobserved requirement must be scored"

    def test_s2_changed(self, report, record_property):
        'The reference change to packages/babel-parser/src/types.js is present. Any edit that achieves the same observable behaviour satisfies this.'
        c = _record(report, record_property, 'E2-req:S2-changed')
        assert c.weight > 0, "an unobserved requirement must be scored"


